-- 0001_initial: first version of the schema.
-- Every id is a UUID stored as text and generated by the application.
-- Timestamps are UTC ISO-8601 text. Calendar days are YYYY-MM-DD text.

-- Supertype of everything that is learned and reviewed: a Topic or a Weak Spot.
-- review_state and exercise point here, so each needs only one foreign key.
CREATE TABLE learning_item (
    id        TEXT NOT NULL PRIMARY KEY CHECK (id GLOB '????????-????-????-????-????????????'),
    item_type TEXT NOT NULL CHECK (item_type IN ('topic', 'weak_spot')),
    UNIQUE (id, item_type)
);

-- The kinds of Topic. A lookup table rather than a CHECK, so a new type is a new row,
-- not a schema change. The descriptions also tell the AI where each mistake belongs.
CREATE TABLE topic_type (
    name        TEXT NOT NULL PRIMARY KEY,
    description TEXT NOT NULL
);

INSERT INTO topic_type (name, description) VALUES
    ('grammar', 'Rules for how words and sentences are formed and combined.'),
    ('vocabulary', 'Words and their meanings, grouped by theme or level, and choosing the right word.'),
    ('lexical', 'Words learned as units: collocations, phrasal verbs, dependent prepositions, confusable words, linkers.'),
    ('functions', 'What you do with the language, and the phrases that fit the situation and tone.');

-- The composite foreign key on topic and weak_spot makes the database refuse a
-- row whose learning_item is of the other kind.
-- code: stable slug from the seed file (for example g-past-simple), so a re-import
--   updates a Topic instead of duplicating it. NULL for Topics added by hand.
-- main_level: the CEFR level where the Topic is first taught.
-- also_levels: later levels where it comes back, as semicolon-separated text
--   (for example 'A2;B1'); empty when there are none. Checked in the application.
-- source_ref: entry number(s) in the source program, for tracing a Topic back.
CREATE TABLE topic (
    id               TEXT NOT NULL PRIMARY KEY,
    item_type        TEXT NOT NULL DEFAULT 'topic' CHECK (item_type = 'topic'),
    code             TEXT UNIQUE,
    name             TEXT NOT NULL,
    description      TEXT NOT NULL DEFAULT '',
    type             TEXT NOT NULL REFERENCES topic_type (name),
    category         TEXT,
    main_level       TEXT CHECK (main_level IS NULL
                                 OR main_level IN ('A1', 'A2', 'B1', 'B2', 'C1', 'C2')),
    also_levels      TEXT NOT NULL DEFAULT '',
    unit             TEXT,
    order_in_program INTEGER,
    source_program   TEXT,
    source_ref       TEXT,
    FOREIGN KEY (id, item_type) REFERENCES learning_item (id, item_type)
);
CREATE INDEX idx_topic_type ON topic (type);

CREATE TABLE weak_spot (
    id          TEXT NOT NULL PRIMARY KEY,
    item_type   TEXT NOT NULL DEFAULT 'weak_spot' CHECK (item_type = 'weak_spot'),
    name        TEXT NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    created_at  TEXT NOT NULL,
    FOREIGN KEY (id, item_type) REFERENCES learning_item (id, item_type)
);

CREATE TABLE weak_spot_topic (
    weak_spot_id TEXT NOT NULL REFERENCES weak_spot (id) ON DELETE CASCADE,
    topic_id     TEXT NOT NULL REFERENCES topic (id) ON DELETE CASCADE,
    PRIMARY KEY (weak_spot_id, topic_id)
);
CREATE INDEX idx_weak_spot_topic_topic ON weak_spot_topic (topic_id);

CREATE TABLE review_state (
    learning_item_id TEXT NOT NULL PRIMARY KEY REFERENCES learning_item (id),
    status           TEXT NOT NULL DEFAULT 'New'
                     CHECK (status IN ('New', 'Learning', 'Reviewing', 'Mastered')),
    next_review_date TEXT,
    interval_step    INTEGER NOT NULL DEFAULT 0 CHECK (interval_step >= 0),
    updated_at       TEXT NOT NULL
);
CREATE INDEX idx_review_state_due ON review_state (next_review_date);

CREATE TABLE text (
    id           TEXT NOT NULL PRIMARY KEY CHECK (id GLOB '????????-????-????-????-????????????'),
    content      TEXT NOT NULL,
    submitted_at TEXT NOT NULL
);

CREATE TABLE mistake (
    id           TEXT NOT NULL PRIMARY KEY CHECK (id GLOB '????????-????-????-????-????????????'),
    text_id      TEXT NOT NULL REFERENCES text (id),
    weak_spot_id TEXT NOT NULL REFERENCES weak_spot (id),
    original     TEXT NOT NULL,
    correction   TEXT NOT NULL,
    explanation  TEXT NOT NULL DEFAULT '',
    dismissed    INTEGER NOT NULL DEFAULT 0 CHECK (dismissed IN (0, 1)),
    created_at   TEXT NOT NULL
);
CREATE INDEX idx_mistake_text ON mistake (text_id);
CREATE INDEX idx_mistake_weak_spot ON mistake (weak_spot_id);

CREATE TABLE exercise (
    id               TEXT NOT NULL PRIMARY KEY
                     CHECK (id GLOB '????????-????-????-????-????????????'),
    learning_item_id TEXT NOT NULL REFERENCES learning_item (id),
    type             TEXT NOT NULL CHECK (type IN (
                         'fill_in_the_blank', 'correct_the_sentence',
                         'multiple_choice', 'rewrite_the_sentence')),
    prompt           TEXT NOT NULL,
    answer           TEXT NOT NULL,
    options_json     TEXT CHECK (options_json IS NULL OR json_valid(options_json)),
    mistake_id       TEXT REFERENCES mistake (id),
    source           TEXT NOT NULL CHECK (source IN ('mistake', 'generic')),
    created_at       TEXT NOT NULL,
    CHECK (type <> 'multiple_choice' OR options_json IS NOT NULL)
);
CREATE INDEX idx_exercise_learning_item ON exercise (learning_item_id);
CREATE INDEX idx_exercise_mistake ON exercise (mistake_id);

CREATE TABLE attempt (
    id          TEXT NOT NULL PRIMARY KEY CHECK (id GLOB '????????-????-????-????-????????????'),
    exercise_id TEXT NOT NULL REFERENCES exercise (id),
    correct     INTEGER NOT NULL CHECK (correct IN (0, 1)),
    answered_at TEXT NOT NULL,
    local_date  TEXT NOT NULL
);
CREATE INDEX idx_attempt_exercise_day ON attempt (exercise_id, local_date);

-- Names and descriptions of every learning item in one place.
CREATE VIEW learning_item_detail AS
SELECT id, item_type, name, description FROM topic
UNION ALL
SELECT id, item_type, name, description FROM weak_spot;
